    if (N < 0) {
        throw new IllegalArgumentException("Number of people must be non-negative");
    }
    if (N <= 1) {
        return 0; // no swaps needed for 0 or 1 person
    }
    if (N % 2 == 1) {
        // Odd number of people: each of the (N-1)/2 pairs takes 2 minutes
        return N - 1;
    }
    // Even number of people
    if (N % 4 == 0) {
        // If N is a multiple of 4, each pair takes 1 minute
        return N / 2;
    } else {
        // If N modulo 4 equals 2, each pair takes 2 minutes
        return N;
    }
}

