public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Normalize strings: treat null as empty string
    for (int i = 0; i < strings.size(); i++) {
        if (strings.get(i) == null) {
            strings.set(i, "");
        }
    }

    // If any string is empty, no common non-empty substring exists
    for (String s : strings) {
        if (s.isEmpty()) {
            return 0;
        }
    }

    // Find the length of the shortest string
    int maxPossibleLength = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s.length() < maxPossibleLength) {
            maxPossibleLength = s.length();
        }
    }

    int low = 1;
    int high = maxPossibleLength;
    int best = 0;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (hasCommonSubstring(strings, mid)) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return best;
}

private boolean hasCommonSubstring(List<String> strings, int len) {
    Set<String> common = null;

    for (String s : strings) {
        Set<String> candidate = new HashSet<>();

        // Add all substrings of length len from the original string
        int n = s.length();
        if (n >= len) {
            for (int i = 0; i <= n - len; i++) {
                candidate.add(s.substring(i, i + len));
            }
        }

        // Add all substrings of length len from the reversed string
        String rev = new StringBuilder(s).reverse().toString();
        int r = rev.length();
        if (r >= len) {
            for (int i = 0; i <= r - len; i++) {
                candidate.add(rev.substring(i, i + len));
            }
        }

        if (common == null) {
            common = candidate;
        } else {
            common.retainAll(candidate);
        }

        if (common == null || common.isEmpty()) {
            return false;
        }
    }

    return !common.isEmpty();
}

