                    if (maxLength == n) {
                        return maxLength;
                    }
                }
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        // Handle potential null or irregular rows
        int cols = (grid[i] == null) ? 0 : grid[i].length;
        visited[i] = new boolean[cols];
    }

    int deposits = 0;
    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            continue;
        }
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                dfs(r, c, grid, visited);
            }
        }
    }
    return deposits;
}

private static void dfs(int r, int c, char[][] grid, boolean[][] visited) {
    if (r < 0 || r >= grid.length) {
        return;
    }
    if (grid[r] == null || c < 0 || c >= grid[r].length) {
        return;
    }
    if (visited[r][c] || grid[r][c] != '@') {
        return;
    }
    visited[r][c] = true;
    dfs(r + 1, c, grid, visited);
    dfs(r - 1, c, grid, visited);
    dfs(r, c + 1, grid, visited);
    dfs(r, c - 1, grid, visited);
}

