public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int m = grid.length;
    boolean[][] visited = new boolean[m][];
    for (int i = 0; i < m; i++) {
        if (grid[i] != null) {
            visited[i] = new boolean[grid[i].length];
        } else {
            visited[i] = new boolean[0];
        }
    }
    int count = 0;
    // 8-directional moves
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int i = 0; i < m; i++) {
        if (grid[i] == null) continue;
        int n = grid[i].length;
        for (int j = 0; j < n; j++) {
            if (grid[i][j] != '@' || visited[i][j]) {
                continue;
            }
            count++;
            java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
            stack.push(new int[]{i, j});
            visited[i][j] = true;
            while (!stack.isEmpty()) {
                int[] cell = stack.pop();
                int r = cell[0];
                int c = cell[1];
                for (int d = 0; d < 8; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr < 0 || nr >= m) {
                        continue;
                    }
                    if (grid[nr] == null || nc < 0 || nc >= grid[nr].length) {
                        continue;
                    }
                    if (!visited[nr][nc] && grid[nr][nc] == '@') {
                        visited[nr][nc] = true;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }
    return count;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[grid.length][];
    for (int i = 0; i < grid.length; i++) {
        if (grid[i] == null) {
            visited[i] = new boolean[0];
            continue;
        }
        visited[i] = new boolean[grid[i].length];
    }
    int deposits = 0;
    for (int i = 0; i < grid.length; i++) {
        if (grid[i] == null) continue;
        for (int j = 0; j < grid[i].length; j++) {
            if (!visited[i][j] && grid[i][j] == '@') {
                deposits++;
                dfs(grid, visited, i, j);
            }
        }
    }
    return deposits;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j) {
    if (i < 0 || i >= grid.length) return;
    if (grid[i] == null || j < 0 || j >= grid[i].length) return;
    if (visited[i][j] || grid[i][j] != '@') return;
    visited[i][j] = true;
    dfs(grid, visited, i - 1, j);
    dfs(grid, visited, i + 1, j);
    dfs(grid, visited, i, j - 1);
    dfs(grid, visited, i, j + 1);
}

public static int maxRegions(int N) {
    // For 0 or negative triangles, the entire plane is a single region.
    if (N <= 0) {
        return 1;
    }
    // Maximum number of regions with N triangles is 3 * N * (N - 1) + 2
    // Calculate using long to avoid overflow on intermediate steps.
    long result = 3L * N * (N - 1) + 2;
    // Convert to int; caller must ensure the value fits within int range.
    return (int) result;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("N must be non-negative");
    }
    if (N == 0) {
        return 1; // The entire plane is a single region
    }
    long result = 3L * N * (long)(N - 1) + 2L;
    if (result > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Result exceeds integer range");
    }
    return (int) result;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        // No triangles create a single region (the whole plane).
        return 1;
    }
    long result = 2L + 3L * N * (long)(N - 1);
    if (result > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Maximum regions exceed integer range for N = " + N);
    }
    return (int) result;
}

