    // build frequency map
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        // Check if there's another element that is half of n
        // n must be even (including negative evens)
        if (n % 2 == 0) {
            int half = n / 2;
            Integer halfCount = freq.get(half);
            if (halfCount != null) {
                // If the half value is not the same as n, any occurrence suffices
                // If it is the same, we need at least two occurrences
                if (half != n || halfCount > 1) {
                    count++;
                }
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (n <= 0 || start == null || end == null) {
        return "cannot be travelled";
    }
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    if (start.length == 0) {
        return "cannot be travelled";
    }
    // If start and end coordinates are identical, travel is trivially possible
    java.util.Arrays.sort(start);
    java.util.Arrays.sort(end);
    if (java.util.Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Mapping from coordinate representation to a unique integer ID
    java.util.HashMap<String, Integer> coordToId = new java.util.HashMap<>();
    // Adjacency list
    java.util.HashMap<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();
    int idCounter = 0;

    // Helper to get or create ID for a coordinate array
    java.util.function.Function<int[], Integer> getId = (coords) -> {
        // Create a string key
        String key = java.util.Arrays.toString(coords);
        Integer id = coordToId.get(key);
        if (id == null) {
            id = idCounter++;
            coordToId.put(key, id);
            adj.put(id, new java.util.ArrayList<Integer>());
        }
        return id;
    };

    // Insert start and end into mapping
    int startId = getId.apply(start);
    int endId = getId.apply(end);

    // Process each path
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null) {
                continue; // skip null rows
            }
            // Case 1: path specified by pair of node IDs
            if (p.length == 2) {
                int u = p[0];
                int v = p[1];
                // Ensure adjacency lists exist
                adj.computeIfAbsent(u, k -> new java.util.ArrayList<Integer>());
                adj.computeIfAbsent(v, k -> new java.util.ArrayList<Integer>());
                adj.get(u).add(v);
                adj.get(v).add(u);
                // For consistency with start and end, add them to mapping if not present
                coordToId.putIfAbsent(java.util.String.valueOf(u), u); // not used as key for coords
                coordToId.putIfAbsent(java.util.String.valueOf(v), v);
            }
            // Case 2: path specified by two coordinate arrays of length n each
            else if (p.length == 2 * n) {
                int[] coord1 = java.util.Arrays.copyOfRange(p, 0, n);
                int[] coord2 = java.util.Arrays.copyOfRange(p, n, 2 * n);
                int id1 = getId.apply(coord1);
                int id2 = getId.apply(coord2);
                adj.get(id1).add(id2);
                adj.get(id2).add(id1);
            } else {
                // Invalid path specification
                return "cannot be travelled";
            }
        }
    }

    // Quick existence check: if start or end have no adjacency and are not the same,
    // we still may travel if they are isolated but equal, otherwise impossible
    if (startId == endId) {
        return "can be travelled";
    }
    // If start or end have no connections and not directly connected to each other
    if (!adj.containsKey(startId) || !adj.containsKey(endId)) {
        return "cannot be travelled";
    }

    // Breadth-first search from startId
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    queue.add(startId);
    visited.add(startId);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endId) {
            return "can be travelled";
        }
        java.util.List<Integer> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (int nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic input validation
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n || paths == null) {
        return "cannot be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    adjacency.put(startKey, new java.util.ArrayList<>());
    adjacency.put(endKey, new java.util.ArrayList<>());

    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            // Invalid path format; skip or consider as error
            return "cannot be travelled";
        }
        int[] nodeA = new int[n];
        int[] nodeB = new int[n];
        System.arraycopy(path, 0, nodeA, 0, n);
        System.arraycopy(path, n, nodeB, 0, n);
        String keyA = java.util.Arrays.toString(nodeA);
        String keyB = java.util.Arrays.toString(nodeB);

        adjacency.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adjacency.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // If start equals end, can travel
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // If start or end not present in graph, cannot travel
    if (!adjacency.containsKey(startKey) || !adjacency.containsKey(endKey)) {
        return "cannot be travelled";
    }

    // Breadth-First Search to find path
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : adjacency.getOrDefault(current, java.util.Collections.emptyList())) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    // No path found
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic input validation
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list
    java.util.List<java.util.List<Integer>> adjacency = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adjacency.add(new java.util.ArrayList<>());
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) {
            continue;
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue;
        }
        adjacency.get(u).add(v);
        adjacency.get(v).add(u); // Assume undirected graph
    }

    // BFS to check reachability
    boolean[] visited = new boolean[n];
    java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
    visited[startNode] = true;
    queue.add(startNode);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endNode) {
            return "can be travelled";
        }
        for (int neighbor : adjacency.get(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) return "cannot be travelled";
    if (start == null || end == null || start.length < 2 || end.length < 2) return "cannot be travelled";
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) return "cannot be travelled";
    if (sx == ex && sy == ey) return "can be travelled";

    int total = n * n;
    @SuppressWarnings("unchecked")
    java.util.ArrayList<Integer>[] adj = new java.util.ArrayList[total];
    for (int i = 0; i < total; i++) adj[i] = new java.util.ArrayList<>();

    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length < 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
            int u = x1 * n + y1;
            int v = x2 * n + y2;
            if (Math.abs(x1 - x2) + Math.abs(y1 - y2) == 1) {
                adj[u].add(v);
                adj[v].add(u);
            }
        }
    }

    boolean[] visited = new boolean[total];
    java.util.Deque<Integer> queue = new java.util.ArrayDeque<>();
    int startIdx = sx * n + sy;
    queue.add(startIdx);
    visited[startIdx] = true;
    int targetIdx = ex * n + ey;

    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                if (nb == targetIdx) return "can be travelled";
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic parameters
    if (n <= 0 || start == null || end == null) {
        return "cannot be travelled";
    }
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }
    // Special case when start == end
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }
    // Build adjacency map from paths
    java.util.Map<String, java.util.Set<String>> adjacency = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 4) continue;
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            // Validate coordinates within bounds
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n) continue;
            if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
            String a = x1 + "," + y1;
            String b = x2 + "," + y2;
            adjacency.computeIfAbsent(a, k -> new java.util.HashSet<>()).add(b);
            adjacency.computeIfAbsent(b, k -> new java.util.HashSet<>()).add(a);
        }
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    // BFS to find path
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.Set<String> neighbors = adjacency.get(current);
        if (neighbors == null) continue;
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in format \"MM dd yyyy\"");
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.Month monthObj = localDate.getMonth();
        String monthName = monthObj.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int dayOfMonth = localDate.getDayOfMonth();
        String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return monthName + " " + dayOfMonth + ", " + year + " is a " + weekday;
    } catch (NumberFormatException | java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date format or value", e);
    }
}

