    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid date";
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            return "Invalid date";
        }

        java.time.LocalDate ld = java.time.LocalDate.of(year, month, day);

        String monthName = ld.getMonth()
                             .getDisplayName(java.time.format.TextStyle.FULL,
                                             java.util.Locale.ENGLISH);
        String weekday = ld.getDayOfWeek()
                           .getDisplayName(java.time.format.TextStyle.FULL,
                                           java.util.Locale.ENGLISH);

        return monthName + " " + ld.getDayOfMonth() + ", " + year + " is a " + weekday;

    } catch (Exception e) {
        return "Invalid date";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date: null";
    }
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date: " + date;
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            return "Invalid date: " + date;
        }
        if (year < 1) {
            return "Invalid date: " + date;
        }

        // Set up calendar
        java.util.Calendar cal = java.util.Calendar.getInstance();
        cal.setLenient(false);
        cal.set(java.util.Calendar.YEAR, year);
        cal.set(java.util.Calendar.MONTH, month - 1); // 0-based
        cal.set(java.util.Calendar.DAY_OF_MONTH, day);

        // After setting, validate
        if (cal.get(java.util.Calendar.MONTH) != month - 1 ||
            cal.get(java.util.Calendar.DAY_OF_MONTH) != day) {
            return "Invalid date: " + date;
        }

        // Month names
        String[] monthNames = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };

        // Weekday names
        String[] dayNames = {
            "Sunday", "Monday", "Tuesday", "Wednesday",
            "Thursday", "Friday", "Saturday"
        };

        String monthName = monthNames[month - 1];
        String weekdayName = dayNames[cal.get(java.util.Calendar.DAY_OF_WEEK) - 1];

        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (NumberFormatException | java.util.IllegalArgumentException e) {
        return "Invalid date: " + date;
    } catch (Exception e) {
        return "Error processing date: " + date;
    }
}

public int[] twoSum(int[] nums, int target) {
