public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int n = nums.length;
    // Find the index of the smallest element (pivot)
    int low = 0, high = n - 1;
    while (low < high) {
        int mid = (low + high) >>> 1;
        if (nums[mid] > nums[high]) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    int pivot = low; // index of smallest element

    // Determine which side to search
    if (target >= nums[0]) {
        low = 0;
        high = pivot - 1;
    } else {
        low = pivot;
        high = n - 1;
    }

    // Standard binary search on the chosen side
    while (low <= high) {
        int mid = (low + high) >>> 1;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

