public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }

    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }

    // if k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // already handled for even k
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
