        // Cannot pair odd number of elements
        return false;
    }

    // Count remainders modulo k
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 also needs even count
    if (k % 2 == 0) {
        int mid = k / 2;
        if (freq[mid] % 2 != 0) {
            return false;
        }
    }

    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            // Already handled for even k at r = k/2
            continue;
        }
        if (freq[r] != freq[k - r]) {
