}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || arr.length == 0 || k <= 0) {
        return false;
    }
    // Must be able to form pairs: array length must be even
    if (arr.length % 2 != 0) {
        return false;
    }

    // Count frequencies of remainders modulo k
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int r = ((num % k) + k) % k; // Ensure non‑negative remainder
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }

    java.util.HashSet<Integer> visited = new java.util.HashSet<>();

    for (int r : freq.keySet()) {
        if (visited.contains(r)) {
            continue;
        }

        int countR = freq.get(r);

        // Handle remainder 0
        if (r == 0) {
            if (countR % 2 != 0) {
                return false;
            }
            visited.add(r);
            continue;
        }

        // Handle remainder that pairs with itself (k even, r == k/2)
        if (k % 2 == 0 && r == k / 2) {
            if (countR % 2 != 0) {
                return false;
            }
            visited.add(r);
            continue;
        }

        int complement = k - r;
        int countComp = freq.getOrDefault(complement, 0);

        if (countR != countComp) {
            return false;
        }

        visited.add(r);
        visited.add(complement);
    }

    return true;
}

