public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    if (edges.length != n - 1) {
        throw new IllegalArgumentException("Edges length must be n-1 for a tree");
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            throw new IllegalArgumentException("Each edge must have two endpoints");
        }
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge endpoints out of bounds");
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    boolean[] visited = new boolean[n];
    return dfs(0, -1, graph, hasApple, visited);
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int total = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int childCost = dfs(child, node, graph, hasApple, visited);
        if (childCost > 0 || hasApple[child]) {
            total += childCost + 2;
        }
    }
    // If this node has an apple but no children with apples, childCost==0 and
    // hasApple[node] may be true, but we do not need to add time here.
    // The parent will account for traversing to this node.
    return total;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array length must equal n");
    }

    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }

    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length < 2) continue;
            int u = e[0];
            int v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    }

    int[] total = new int[1];
    dfs(0, -1, graph, hasApple, total);
    return total[0];
}

private boolean dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple, int[] total) {
    boolean subtreeHasApple = hasApple[node];
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        boolean childHas = dfs(neighbor, node, graph, hasApple, total);
        if (childHas) {
            total[0] += 2;
            subtreeHasApple = true;
        }
    }
    return subtreeHasApple;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    // Build adjacency list
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    if (edges != null) {
        for (int[] edge : edges) {
            if (edge == null || edge.length != 2) {
                continue; // skip invalid edges
            }
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue; // skip out‑of‑range indices
            }
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
    }

    // Ensure hasApple array is valid; missing entries are considered false
    boolean[] apples = new boolean[n];
    if (hasApple != null) {
        for (int i = 0; i < Math.min(n, hasApple.length); i++) {
            apples[i] = hasApple[i];
        }
    }

    final int[] totalTime = {0};

    // DFS to compute time; returns true if subtree contains an apple
    class Helper {
        boolean dfs(int node, int parent) {
            boolean hasInSubtree = apples[node];
            for (int child : adj.get(node)) {
                if (child == parent) {
                    continue;
                }
                boolean childHasApple = dfs(child, node);
                if (childHasApple) {
                    totalTime[0] += 2; // go to child and back
                    hasInSubtree = true;
                }
            }
            return hasInSubtree;
        }
    }

    Helper h = new Helper();
    h.dfs(0, -1);

    return totalTime[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
    try {
        for (int[] e : edges) {
            if (e == null || e.length != 2) continue;
            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    } catch (Exception e) {
        return 0;
    }

    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    java.util.List<Integer> order = new java.util.ArrayList<>();
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    boolean[] visited = new boolean[n];
    visited[0] = true;
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int nei : graph[node]) {
            if (!visited[nei]) {
                visited[nei] = true;
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    boolean[] hasAppleInSubtree = new boolean[n];
    int totalTime = 0;
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        boolean hasAppleHere = hasApple[node];
        boolean foundInChildren = false;
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            if (hasAppleInSubtree[nei]) {
                foundInChildren = true;
                totalTime += 2; // go to child and back
            }
        }
        hasAppleInSubtree[node] = hasAppleHere || foundInChildren;
    }
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list using arrays to avoid imports
    int[] degree = new int[n];
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        degree[u]++;
        degree[v]++;
    }
    int[][] graph = new int[n][];
    for (int i = 0; i < n; i++) {
        graph[i] = new int[degree[i]];
    }
    int[] idx = new int[n];
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u][idx[u]++] = v;
        graph[v][idx[v]++] = u;
    }

    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, int[][] graph, boolean[] hasApple) {
    int time = 0;
    int[] neighbors = graph[node];
    if (neighbors != null) {
        for (int child : neighbors) {
            if (child == parent) {
                continue;
            }
            int childTime = dfs(child, node, graph, hasApple);
            if (childTime > 0 || hasApple[child]) {
                time += childTime + 2;
            }
        }
    }
    return time;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    // Frequency array for ASCII characters
    int[] freq = new int[256];
    for (char c : s.toCharArray()) {
        freq[c]++; // char is implicitly converted to int index
    }
    int remaining = s.length();
    StringBuilder result = new StringBuilder();

    while (remaining > 0) {
        // Ascending phase
        int prev = -1; // no previous character at start
        while (true) {
            int start = (prev == -1) ? 0 : prev + 1; // next smallest strictly greater
            int pick = -1;
            for (int i = start; i < 256; i++) {
                if (freq[i] > 0) {
                    pick = i;
                    break;
                }
            }
            if (pick == -1) {
                break; // cannot pick more in ascending phase
            }
            freq[pick]--;
            remaining--;
            result.append((char) pick);
            prev = pick;
        }

        // Descending phase
        prev = -1; // reset previous character
        while (true) {
            int start = (prev == -1) ? 255 : prev - 1; // next largest strictly smaller
            int pick = -1;
            for (int i = start; i >= 0; i--) {
                if (freq[i] > 0) {
                    pick = i;
                    break;
                }
            }
            if (pick == -1) {
                break; // cannot pick more in descending phase
            }
            freq[pick]--;
            remaining--;
            result.append((char) pick);
            prev = pick;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    // Frequency array for all ASCII characters
    int[] freq = new int[128];
    for (char ch : s.toCharArray()) {
        if (ch >= freq.length) {
            // Expand array if non-ASCII characters appear
            throw new IllegalArgumentException("Unsupported character: " + ch);
        }
        freq[ch]++;
    }

    StringBuilder res = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Ascending pass
        for (int i = 0; i < 128 && remaining > 0; i++) {
            if (freq[i] > 0) {
                res.append((char) i);
                freq[i]--;
                remaining--;

                // Continue ascending from this character
                while (remaining > 0) {
                    int j = i + 1;
                    while (j < 128 && freq[j] == 0) {
                        j++;
                    }
                    if (j == 128) {
                        break;
                    }
                    res.append((char) j);
                    freq[j]--;
                    remaining--;
                    i = j;
                }

                // Descending pass
                for (int k = 127; k >= 0 && remaining > 0; k--) {
                    if (freq[k] > 0) {
                        res.append((char) k);
                        freq[k]--;
                        remaining--;

                        // Continue descending from this character
                        int curr = k;
                        while (remaining > 0) {
                            int m = curr - 1;
                            while (m >= 0 && freq[m] == 0) {
                                m--;
                            }
                            if (m < 0) {
                                break;
                            }
                            res.append((char) m);
                            freq[m]--;
                            remaining--;
                            curr = m;
                        }
                        // After completing descending, break to outer loop
                        break;
                    }
                }
                // Break to start next outer iteration
                break;
            }
        }
    }

    return res.toString();
}

public String sortString(String s) {
