public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    long totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    // dp[k] contains all achievable sums using k elements
    @SuppressWarnings("unchecked")
    Set<Long>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0L);

    for (int val : nums) {
        // Iterate from higher k to avoid overwriting data needed for this iteration
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1].isEmpty()) {
                continue;
            }
            for (Long prev : dp[k - 1]) {
                dp[k].add(prev + val);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum not an integer
        }
        long target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Use DP: possible[k][s] == true if a subset of size k with sum s exists
    boolean[][] possible = new boolean[n + 1][totalSum + 1];
    possible[0][0] = true;
    for (int num : nums) {
        // traverse k and sum in reverse to avoid reuse of the same element
        for (int k = n - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (possible[k][s]) {
                    possible[k + 1][s + num] = true;
                }
            }
        }
    }
    for (int k = 1; k < n; k++) {
        // Check if target sum for this subset size is integer
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (target >= 0 && target <= totalSum && possible[k][target]) {
            return true;
        }
    }
    return false;
}

