    }
    // dp[i] will store the set of possible sums using exactly i numbers.
    @SuppressWarnings("unchecked")
    HashSet<Long>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0L);

    for (int num : nums) {
        // Iterate sizes backwards to avoid using the same number multiple times.
        for (int size = n - 1; size >= 1; size--) {
            if (dp[size - 1].isEmpty()) continue;
            for (Long prevSum : dp[size - 1]) {
                dp[size].add(prevSum + num);
            }
        }
    }

    // Check for each possible subset size k whether a subset with correct sum exists.
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum must be integer
        }
        long targetSum = (totalSum * k) / n;
        if (dp[k].contains(targetSum)) {
