}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[s] = set of sums achievable with subset size s
    java.util.List<java.util.HashSet<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int idx = 0; idx < n; idx++) {
        int num = nums[idx];
        int maxSize = Math.min(idx, n - 1);
        for (int size = maxSize; size >= 1; size--) {
            java.util.HashSet<Integer> prevSet = dp.get(size - 1);
            java.util.HashSet<Integer> currSet = dp.get(size);
            for (int s : prevSet) {
                currSet.add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((long) totalSum * k % n != 0) continue;
        int target = (int) ((long) totalSum * k / n);
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;

    // If there is only one step, you can start at step 1 (outside the staircase) and incur zero cost.
    if (n == 1) {
        return 0;
    }

    // dp[0] = dp[1] = 0 because you can start before step 0 or before step 1 with no cost.
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]

    // Compute dp[i] iteratively
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int cur = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = cur;
    }

    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        return 0;
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        // We can start from beyond the first step, so no cost needed.
        return 0;
    }
    // Use two variables to store the minimum cost to reach the previous two steps.
    int prevPrev = cost[0]; // cost to reach step 0
    int prev = cost[1];     // cost to reach step 1
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = current;
    }
    // The top can be reached from either the last step or the second last step.
    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    // Use two variables to save space (dp[i-2] and dp[i-1])
    int prevPrev = cost[0];          // dp[0]
    int prev = cost[1];              // dp[1]
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = curr;
    }
    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        // No steps to climb, cost is zero.
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Only one step: must start at it and pay its cost.
        return cost[0];
    }
    // dp[i] represents the minimum cost to reach step i.
    // We only need the previous two values.
    int prevPrev = 0; // dp[i-2]
    int prev = 0;     // dp[i-1]
    int current = 0;  // dp[i]
    for (int i = 2; i <= n; i++) {
        // We can come to step i from step i-1 or i-2.
        current = Math.min(prev + cost[i - 1], prevPrev + cost[i - 2]);
        prevPrev = prev;
        prev = current;
    }
    return current;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("cost array cannot be null or empty");
    }
    // Use two variables to keep the minimal cost to reach the previous two steps
    int prevPrev = 0; // dp[i-2]
    int prev = 0;    // dp[i-1]
    int curr = 0;    // dp[i]
    for (int i = 2; i <= cost.length; i++) {
        curr = Math.min(prevPrev + cost[i - 2], prev + cost[i - 1]);
        prevPrev = prev;
        prev = curr;
    }
    // For cost.length == 1, the loop above is skipped and prev remains 0, which is correct
    return prev;
}

