public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    long total = 1L << k;
    Set<Long> seen = new HashSet<>((int) Math.min(total, Integer.MAX_VALUE));
    long mask = total - 1;
    long code = 0L;
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen.add(code);
    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        seen.add(code);
        if (seen.size() == total) {
            return true;
        }
    }
    return seen.size() == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;

    // If k is too large to allocate an array, fall back to a HashSet
    if (k > 20) {
        java.util.HashSet<Integer> seen = new java.util.HashSet<>();
        int mask = 0;
        int limitMask = (1 << k) - 1; // won't overflow since k <= 20 here
        for (int i = 0; i < n; i++) {
            mask = ((mask << 1) & limitMask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(mask);
                if (seen.size() == (1 << k)) return true;
            }
        }
        return false;
    }

    int totalCodes = 1 << k;
