public int minOperations(int n) {
    if (n <= 0) return 0;
    int t = n / 2;                     // first index with arr[i] >= n
    int m = n - t;                     // number of indices with surplus
    long a = 2L * t + 1 - n;            // first surplus value
    long result = (long) m * a + (long)(m - 1) * m; // sum of all surpluses
    // The result fits in int for the given problem constraints
    return (int) result;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    // Use long for intermediate calculations to avoid overflow
    if (n % 2 == 0) {
        long result = ((long) n * n) / 4;
        return (int) result;
    } else {
        long result = (((long) n * n) - 1) / 4;
        return (int) result;
    }
}

public int minOperations(int n) {
    // Handle non-positive input gracefully
    if (n <= 0) {
        return 0;
    }

    // The target value each element must reach is the average of the array.
    // Sum of the array arr[i] = 2*i + 1 for i = 0..n-1 is n^2, so the target is n.
    int target = n;
    long operations = 0L;

    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;
        if (value > target) {
            operations += value - target;
        }
    }

    // The result fits in an int for reasonable input sizes; cast safely.
    return (int) operations;
}

