    // If n is non-positive, no array to process.
    if (n <= 0) {
        return 0;
    }
    // For even n: number of operations = (n/2)^2
    // For odd n: number of operations = ((n-1)/2) * ((n+1)/2)
    if (n % 2 == 0) {
        int m = n / 2;
        // Use long intermediate to prevent overflow for large n
        long ops = (long) m * m;
        return (int) ops;
    } else {
        int m = (n - 1) / 2;
        long ops = (long) m * (m + 1);
        return (int) ops;
    }
}

