public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be positive");
    }
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        long next = (long) fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) {
            break;
        }
        fib.add((int) next);
    }
    int count = 0;
    for (int i = fib.size() - 1; i >= 0 && k > 0; i--) {
        if (fib.get(i) <= k) {
            k -= fib.get(i);
            count++;
        }
    }
    return count;
}

