public int kthFactor(int n, int k) {
    // Validate input: n and k must be positive integers
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.List<Integer> factors = new java.util.ArrayList<>();

    // Find all factors of n
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int complement = n / i;
            if (complement != i) {
                factors.add(complement);
            }
        }
    }

    // Sort factors in ascending order
    java.util.Collections.sort(factors);

    // Return the k-th factor if it exists, otherwise -1
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int limit = (int) Math.sqrt(n);
    // arrays large enough to hold all factors up to sqrt(n)
    int[] small = new int[limit + 1];
    int[] big = new int[limit + 1];
    int smallSize = 0, bigSize = 0;

    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small[smallSize++] = i;
            int counterpart = n / i;
            if (i != counterpart) {
                big[bigSize++] = counterpart;
            }
        }
    }

    if (k <= smallSize) {
        return small[k - 1];
    }
    int remaining = k - smallSize;
    if (remaining <= bigSize) {
        // big array is stored in decreasing order, so pick from the end
        return big[bigSize - remaining];
    }
    return -1;
}

