public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Character.toUpperCase(top) == Character.toUpperCase(c) && top != c) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len == 0) {
            stack.append(c);
            continue;
        }
        char top = stack.charAt(len - 1);
        // The ASCII difference between 'a' and 'A' is 32
        if (Math.abs(c - top) == 32) {
            stack.deleteCharAt(len - 1);
        } else {
            stack.append(c);
        }
    }
    return stack.toString();
}

