public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    java.util.Deque<java.util.AbstractMap.SimpleEntry<Integer, java.util.HashSet<String>>> stack =
            new java.util.ArrayDeque<>();
    stack.push(new java.util.AbstractMap.SimpleEntry<>(0, new java.util.HashSet<>()));

    while (!stack.isEmpty()) {
        java.util.AbstractMap.SimpleEntry<Integer, java.util.HashSet<String>> entry = stack.pop();
        int idx = entry.getKey();
        java.util.HashSet<String> used = entry.getValue();

        if (idx == n) {
            if (used.size() > max) {
                max = used.size();
            }
            continue;
        }

        for (int len = 1; idx + len <= n; len++) {
            String sub = s.substring(idx, idx + len);
            if (!used.contains(sub)) {
                java.util.HashSet<String> newSet = new java.util.HashSet<>(used);
                newSet.add(sub);
                stack.push(new java.util.AbstractMap.SimpleEntry<>(idx + len, newSet));
            }
        }
    }

    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int[] maxCount = {0};
    Set<String> used = new HashSet<>();
    dfs(0, s, used, 0, maxCount);
    return maxCount[0];
}

private void dfs(int index, String s, Set<String> used, int count, int[] maxCount) {
    int n = s.length();
    if (index == n) {
        if (count > maxCount[0]) {
            maxCount[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, s, used, count + 1, maxCount);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int[] maxCount = new int[1];
    try {
        backtrack(0, 0, new java.util.HashSet<>(), s, maxCount);
    } catch (Exception e) {
        // In case of unexpected runtime errors, return 0
        return 0;
    }
    return maxCount[0];
}

private void backtrack(int pos, int count, java.util.Set<String> seen, String s, int[] maxCount) {
    if (pos == s.length()) {
        if (count > maxCount[0]) {
            maxCount[0] = count;
        }
        return;
    }
    for (int i = pos + 1; i <= s.length(); i++) {
        String sub = s.substring(pos, i);
        if (seen.contains(sub)) {
            continue;
        }
        seen.add(sub);
        backtrack(i, count + 1, seen, s, maxCount);
        seen.remove(sub);
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int maxParts = 0;
    // Iterate over all possible split patterns using bitmask
    // bit i (0-indexed) indicates a cut after position i
    int totalMasks = 1 << (n - 1); // n-1 possible cut positions
    for (int mask = 0; mask < totalMasks; mask++) {
        Set<String> seen = new HashSet<>();
        boolean valid = true;
        int last = 0;      // start index of current substring
        int count = 0;     // number of substrings in this partition

        for (int i = 0; i < n - 1; i++) {
            // If there's a cut after position i
            if ((mask & (1 << i)) != 0) {
                String seg = s.substring(last, i + 1);
                if (!seen.add(seg)) { // duplicate substring found
                    valid = false;
                    break;
                }
                count++;
                last = i + 1; // start of next substring
            }
        }

        if (!valid) {
            continue;
        }

        // Add the last segment after the final cut
        String seg = s.substring(last);
        if (!seen.add(seg)) {
            continue; // duplicate in the last segment
        }
        count++;

        if (count > maxParts) {
            maxParts = count;
        }
    }
    return maxParts;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    return dfs(s, 0, new java.util.HashSet<String>());
}

private int dfs(String s, int idx, java.util.Set<String> used) {
    if (idx == s.length()) {
        return 0;
    }
    int max = 0;
    for (int j = idx + 1; j <= s.length(); j++) {
        String sub = s.substring(idx, j);
        if (!used.contains(sub)) {
            used.add(sub);
            int temp = 1 + dfs(s, j, used);
            if (temp > max) {
                max = temp;
            }
            used.remove(sub);
        }
    }
    return max;
}

