public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) { // use long to avoid overflow
        throw new IllegalArgumentException("k is not in the feasible range");
    }
    char[] chars = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int remaining = k - n; // amount to add beyond all 'a'
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can add up to 25 to go from 'a' to 'z'
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

