public static double calculateProbability(int n) {
    // The classic airplane seat problem: the first passenger chooses a random seat.
    // Subsequent passengers sit in their own seat if available, otherwise choose a random free seat.
    // The probability that the last passenger ends up in their own seat is:
    //   1 for n == 1 (only one seat),
    //   1/2 for n >= 2.
    //
    // Handle potential invalid input gracefully:
    if (n <= 0) {
        // Non-positive number of passengers is not meaningful in this context.
        return 0.0;
    }
    return (n == 1) ? 1.0 : 0.5;
}

