public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result; // empty list for invalid range
    }
    // Handle 0 separately since BFS starting from 1-9 won't generate it
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.add(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int lastDigit = num % 10;
        // Append lastDigit - 1 if it's valid
        if (lastDigit > 0) {
            int next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.add(next);
            }
        }
        // Append lastDigit + 1 if it's valid
        if (lastDigit < 9) {
            int next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.add(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

