    }

    // 0 is a stepping number if it lies within the range.
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    // Initialize queue with digits 1 to 9, ensuring we don't exceed 'high'.
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer(i);
        }
    }

    while (!queue.isEmpty()) {
        int current = queue.poll();

        if (current >= low && current <= high) {
            result.add(current);
        }

        // No need to generate children if current already exceeds high.
        if (current > high) {
            continue;
        }

        int lastDigit = current % 10;
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};

        for (int nd : nextDigits) {
            if (nd < 0 || nd > 9) {
                continue;
            }
            long nextNumberLong = (long) current * 10 + nd;
            if (nextNumberLong > high) {
                continue;
            }
            queue.offer((int) nextNumberLong);
        }
    }

    java.util.Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (high < 0) {
        return result; // No non‑negative stepping numbers
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    // Start BFS with digits 1 through 9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    long highLong = high;
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > highLong) {
            continue;
        }
        if (num >= low && num <= highLong) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        // Ensure we do not exceed the bound when appending a new digit
        if (num <= highLong / 10) { // possible to append
            if (lastDigit > 0) {
                long next = num * 10 + (lastDigit - 1);
                queue.offer(next);
            }
            if (lastDigit < 9) {
                long next = num * 10 + (lastDigit + 1);
                queue.offer(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Handle 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }
        int lastDigit = (int) (current % 10);
        long next1 = current * 10 + (lastDigit - 1);
        long next2 = current * 10 + (lastDigit + 1);

        if (lastDigit > 0 && next1 <= high) {
            queue.offer(next1);
        }
        if (lastDigit < 9 && next2 <= high) {
            queue.offer(next2);
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0; // Invalid input, no positive numbers to count
    }
    long count = 0L;
    long factor = 1L; // current positional factor: 1, 10, 100, ...
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10L;
        long higher = n / (factor * 10L);
        if (cur == 0L) {
            count += higher * factor;
        } else if (cur == 1L) {
            count += higher * factor + lower + 1L;
        } else {
            count += (higher + 1L) * factor;
        }
        factor *= 10L;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    if (n <= 0) {  // includes n == 0
        return 0;
    }
    long total = 0;
    long factor = 1;
    while (factor <= n) {
        long lower  = n % factor;                     // right side of current digit
        long cur    = (n / factor) % 10;              // current digit
        long higher = n / (factor * 10);              // left side of current digit

        if (cur == 0) {
            total += higher * factor;
        } else if (cur == 1) {
            total += higher * factor + lower + 1;
        } else { // cur > 1
            total += (higher + 1) * factor;
        }

        // Move to the next higher digit
        if (factor > Long.MAX_VALUE / 10) {
            break; // prevent overflow of factor
        }
        factor *= 10;
    }

    // Since the return type is int, cast the result. It is assumed that the result
    // fits within int range for the intended usage. If it doesn't, it will wrap.
    return (int) total;
}

