public static boolean isPowerOfTwo(int n) {
    // A power of two must be positive and have only a single bit set.
    if (n <= 0) {
        return false;
    }
    // Using the classic bitwise trick: n & (n-1) == 0 for powers of two.
    return (n & (n - 1)) == 0;
}

