public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Ensure all rows have the same length; otherwise, throw an exception.
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must have the same number of columns.");
        }
    }

    int[][] hor = new int[m][n];
    int[][] ver = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                // Treat any non-1 value as 0 (no contribution).
                hor[i][j] = ver[i][j] = diag[i][j] = anti[i][j] = 0;
                continue;
            }

            hor[i][j] = (j > 0) ? hor[i][j - 1] + 1 : 1;
            ver[i][j] = (i > 0) ? ver[i - 1][j] + 1 : 1;
            diag[i][j] = (i > 0 && j > 0) ? diag[i - 1][j - 1] + 1 : 1;
            anti[i][j] = (i > 0 && j < n - 1) ? anti[i - 1][j + 1] + 1 : 1;

            int cellMax = Math.max(Math.max(hor[i][j], ver[i][j]),
                                   Math.max(diag[i][j], anti[i][j]));
            if (cellMax > maxLen) {
                maxLen = cellMax;
            }
        }
    }
    return maxLen;
}

