public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    // Handle case where the first row is empty or rows have varying lengths
    int n = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] != null && mat[i].length > n) {
            n = mat[i].length;
        }
    }
    if (n == 0) {
        return 0;
    }
    int longest = 0;
    int[] vert = new int[n];
    int[] diagPrev = new int[n];
    int[] antiPrev = new int[n];
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            // Skip null rows, reset current state
            vert = new int[n];
            diagPrev = new int[n];
            antiPrev = new int[n];
            continue;
        }
        int rowLen = mat[i].length;
        int[] diagCurr = new int[n];
        int[] antiCurr = new int[n];
        int horiz = 0;
        for (int j = 0; j < n; j++) {
            if (j < rowLen && mat[i][j] == 1) {
                horiz++;
                vert[j] = vert[j] + 1;
                diagCurr[j] = (j > 0 ? diagPrev[j - 1] : 0) + 1;
                antiCurr[j] = (j < n - 1 ? antiPrev[j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz, vert[j]), Math.max(diagCurr[j], antiCurr[j]));
                if (localMax > longest) {
                    longest = localMax;
                }
            } else {
                horiz = 0;
                vert[j] = 0;
                diagCurr[j] = 0;
                antiCurr[j] = 0;
            }
        }
        diagPrev = diagCurr;
        antiPrev = antiCurr;
    }
    return longest;
}

public static String addThousandSeparator(int n) {
    try {
        boolean isNegative = n < 0;
        long value = n; // cast to long to avoid overflow with Integer.MIN_VALUE
        long absValue = Math.abs(value);
        String number = Long.toString(absValue);

        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = number.length() - 1; i >= 0; i--) {
            sb.append(number.charAt(i));
            count++;
            if (count == 3 && i != 0) {
                sb.append('.');
                count = 0;
            }
        }
        sb.reverse();

        if (isNegative) {
            sb.insert(0, '-');
        }

        return sb.toString();
    } catch (Exception e) {
        // In case of unforeseen exceptions return empty string
        return "";
    }
}

public static String addThousandSeparator(int n) {
