    // Handle absolute value for Integer.MIN_VALUE correctly
    String absStr = Long.toString(absVal);
    StringBuilder sb = new StringBuilder(absStr);
    for (int i = sb.length() - 3; i > 0; i -= 3) {
        sb.insert(i, '.');
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long absVal = Math.abs((long) n); // Use long to avoid overflow with Integer.MIN_VALUE
    String numStr = Long.toString(absVal);

    if (numStr.length() <= 3) {
        return (negative ? "-" : "") + numStr;
    }

    StringBuilder sb = new StringBuilder();
    int len = numStr.length();
    // Determine the length of the first group (might be less than 3)
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }

    sb.append(numStr.substring(0, firstGroupLen));
    for (int i = firstGroupLen; i < len; i += 3) {
        sb.append('.');
        sb.append(numStr.substring(i, i + 3));
    }

    return (negative ? "-" : "") + sb.toString();
}

public static String addThousandSeparator(int n) {
    // Preserve the sign and use long to avoid overflow when taking abs of Integer.MIN_VALUE
    boolean negative = n < 0;
    long absValue = Math.abs((long) n);
    String valueStr = Long.toString(absValue);

    StringBuilder result = new StringBuilder();
    int count = 0;

    // Build the string from right to left, inserting '.' after every three digits
    for (int i = valueStr.length() - 1; i >= 0; i--) {
        result.insert(0, valueStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            result.insert(0, '.');
            count = 0;
        }
    }

    // Prepend negative sign if needed
    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly to avoid empty result
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    long value = n;  // promote to long to safely negate Integer.MIN_VALUE
    if (negative) {
        value = -value;
    }

    StringBuilder sb = new StringBuilder();
    int digitCount = 0;

    while (value > 0) {
        sb.append((char) ('0' + (int) (value % 10)));
        value /= 10;
        digitCount++;

        // Insert separator after every three digits, unless this is the last group
        if (digitCount % 3 == 0 && value > 0) {
            sb.append('.');
        }
    }

    if (negative) {
        sb.append('-');
    }

    // The string was built in reverse order
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    final long[] total = {0};

    java.util.HashSet<Integer> squareSet = new java.util.HashSet<>();
    int maxSum = 2 * A[n - 1];
    for (int i = 0; i * i <= maxSum; i++) {
        squareSet.add(i * i);
    }

    java.util.function.IntPredicate isSquare = s -> squareSet.contains(s);

    java.util.function.VoidFunction2<Integer, Integer> dfs = new java.util.function.VoidFunction2<Integer, Integer>() {
        @Override
        public void accept(Integer prevVal, Integer depth) {
            if (depth == n) {
                total[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue; // skip duplicates
                if (prevVal != null && !isSquare.test(prevVal + A[i])) continue;
                used[i] = true;
                accept(A[i], depth + 1);
                used[i] = false;
            }
        }
    };

    dfs.accept(null, 0);
    return (int) total[0];
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    // Build frequency map
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    int maxVal = 0;
    for (int num : A) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
        if (num > maxVal) {
            maxVal = num;
        }
    }

    // Precompute perfect square check up to max possible sum
    int maxSum = maxVal * 2;
    java.util.Set<Integer> perfectSquares = new java.util.HashSet<>();
    for (int i = 2; i * i <= maxSum; i++) {
        perfectSquares.add(i * i);
    }

    // Helper function to perform DFS
    java.util.function.Function<java.util.Map<Integer, Integer>, Integer> dfs = new java.util.function.Function<java.util.Map<Integer, Integer>, Integer>() {
        @Override
        public Integer apply(java.util.Map<Integer, Integer> remaining) {
            int total = 0;
            // If no remaining elements, one valid permutation found
            if (remaining.isEmpty()) {
                return 1;
            }
            // Iterate over each distinct number available
            for (java.util.Map.Entry<Integer, Integer> entry : remaining.entrySet()) {
                int num = entry.getKey();
                int cnt = entry.getValue();
                // If count is zero, skip
                if (cnt == 0) continue;

                // Check adjacency condition with previous element if exists
                Integer prev = (Integer) remaining.get("prev");
                if (prev != null && !perfectSquares.contains(prev + num)) {
                    continue;
                }

                // Place num at current position
                remaining.put(num, cnt - 1);
                // Set previous for next recursion
                remaining.put("prev", num);
                // Recurse
                total += apply(remaining);
                // Backtrack
                remaining.put(num, cnt);
                remaining.remove("prev");
            }
            return total;
        }
    };

    // Since using map for both counts and prev, clone map for recursion
    java.util.Map<Integer, Integer> initial = new java.util.HashMap<>(freq);
    // Start recursion without previous element
    return dfs.apply(initial);
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute list of indices that can follow each index
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    // Precompute perfect square mask up to max possible sum
    int maxSum = 0;
    for (int val : A) maxSum = Math.max(maxSum, val);
    maxSum *= 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int k = 0; k * k <= maxSum; k++) isSquare[k * k] = true;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                adj[i].add(j);
            }
        }
    }

    int fullMask = (1 << n) - 1;
    Map<Long, Integer> memo = new HashMap<>();

    java.util.function.IntBiFunction<Long> dfs = new java.util.function.IntBiFunction<Long>() {
        @Override
        public Long apply(int last, int mask) {
            long key = (((long) mask) << 5) | last; // shift bits to store both
            if (memo.containsKey(key)) return memo.get(key);
            if (mask == fullMask) return 1L;
            long ways = 0;
            HashSet<Integer> seen = new HashSet<>();
            for (int next : adj[last]) {
                if ((mask & (1 << next)) == 0) {
                    int val = A[next];
                    if (!seen.contains(val)) {
                        seen.add(val);
                        ways += apply(next, mask | (1 << next));
                    }
                }
            }
            memo.put(key, (int) ways);
            return ways;
        }
    };

    long total = 0;
    for (int i = 0; i < n; i++) {
        total += dfs.apply(i, 1 << i);
    }

    return (int) total;
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    // Precompute perfect square lookup
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) {
            maxVal = v;
        }
    }
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; (long) s * s <= maxSum; s++) {
        isSquare[s * s] = true;
    }

    // Memoization map key = (mask << 5) | lastIndex
    java.util.Map<Long, Long> memo = new java.util.HashMap<>();
    int fullMask = (1 << n) - 1;

    java.util.function.Function<long[], Long> dfs = new java.util.function.Function<long[], Long>() {
        @Override
        public Long apply(long[] params) {
            int mask = (int) params[0];
            int last = (int) params[1];
            long key = (((long) mask) << 6) | last; // shift bits, 6 bits enough for n<=64
            if (memo.containsKey(key)) {
                return memo.get(key);
            }
            if (mask == fullMask) {
                return 1L;
            }
            long res = 0L;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if (last == -1 || isSquare[A[last] + A[i]]) {
                        res += apply(new long[]{mask | (1 << i), i});
                    }
                }
            }
            memo.put(key, res);
            return res;
        }
    };

    long totalCount = 0L;
    for (int i = 0; i < n; i++) {
        totalCount += dfs.apply(new long[]{1 << i, i});
    }

    // Compute divisor for duplicate values
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    }
    long divisor = 1L;
    long factorial = 1L;
    for (int count : freqMap.values()) {
        if (count > 1) {
            factorial = 1L;
            for (int k = 2; k <= count; k++) {
                factorial *= k;
            }
            divisor *= factorial;
        }
    }
    long result = totalCount / divisor;
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1; // one way to arrange nothing
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();

    java.util.function.Consumer<StackState> dfs = null;
    dfs = (state) -> {
        if (state.size == n) {
            count[0]++;
            return;
        }
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            // skip duplicates
            if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
            if (state.size > 0) {
                int sum = stack.peekLast() + A[i];
                int root = (int) Math.sqrt(sum);
                if (root * root != sum) continue;
            }
            used[i] = true;
            stack.addLast(A[i]);
            state.size++;
            dfs.accept(state);
            state.size--;
            stack.removeLast();
            used[i] = false;
        }
    };

    dfs.accept(new StackState());
    return count[0];
}

