            } else if (r == 0) {          // hit the first row
                c++;
                up = false;
            } else {                      // move diagonally up-right
                r--;
                c++;
            }
        } else {                          // moving down-left
            if (r == rows - 1) {          // hit the last row
                c++;
                up = true;
            } else if (c == 0) {          // hit the first column
                r++;
                up = true;
            } else {                      // move diagonally down-left
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    // Validate input
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0] == null ? 0 : mat[0].length;
    if (n == 0) {
        return new int[0];
    }

    // Optional: verify all rows have the same length, otherwise ignore extra elements
    for (int[] row : mat) {
        if (row == null || row.length != n) {
            // If irregular matrix, adjust n to the minimum valid length
            n = Math.min(n, row == null ? 0 : row.length);
        }
    }
    if (n == 0) {
        return new int[0];
    }

    int total = m * n;
    int[] result = new int[total];
    int idx = 0;

    try {
        for (int sum = 0; sum <= m + n - 2; sum++) {
            int startRow = Math.max(0, sum - (n - 1));
            int endRow = Math.min(m - 1, sum);

            if (sum % 2 == 0) {
                // Even sum: traverse from bottom to top
                for (int i = endRow; i >= startRow; i--) {
                    int j = sum - i;
                    if (j >= 0 && j < n) {
                        result[idx++] = mat[i][j];
                    }
                }
            } else {
                // Odd sum: traverse from top to bottom
                for (int i = startRow; i <= endRow; i++) {
                    int j = sum - i;
                    if (j >= 0 && j < n) {
                        result[idx++] = mat[i][j];
                    }
                }
            }
        }
    } catch (RuntimeException e) {
        // In case of any unexpected runtime issues, return the array collected so far
        int[] truncated = new int[idx];
        System.arraycopy(result, 0, truncated, 0, idx);
        return truncated;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
