    int idx = 0;
    // iterate over diagonals indexed by sum of indices k = i + j
    for (int k = 0; k <= m + n - 2; k++) {
        if (k % 2 == 0) {
            // even k: go from bottom to top along the diagonal
            int row = Math.min(k, m - 1);
            int col = k - row;
            while (row >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            // odd k: go from top to bottom along the diagonal
            int col = Math.min(k, n - 1);
            int row = k - col;
            while (col >= 0 && row < m) {
                result[idx++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

