private static List<String> buildStrobogrammatic(int n, boolean isOuter) {
    List<String> list = new ArrayList<>();
    if (n == 0) {
        list.add("");
        return list;
    }
    if (n == 1) {
        list.add("0");
        list.add("1");
        list.add("8");
        return list;
    }
    List<String> subList = buildStrobogrammatic(n - 2, false);
    for (String sub : subList) {
        if (!isOuter) {
            list.add("0" + sub + "0");
        }
        list.add("1" + sub + "1");
        list.add("6" + sub + "9");
        list.add("8" + sub + "8");
        list.add("9" + sub + "6");
    }
    return list;
}

