public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        // For non-positive inputs, return 0 (no squares needed).
        return 0;
    }

    // Check if n itself is a perfect square.
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }

    // Check if n can be expressed as the sum of two perfect squares.
    for (int i = 1; i <= sqrtN; i++) {
        int square = i * i;
        int remaining = n - square;
        int sqrtRem = (int) Math.sqrt(remaining);
        if (sqrtRem * sqrtRem == remaining) {
            return 2;
        }
    }

    // Determine if the answer is 3 or 4 using Legendre's three-square theorem.
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    // If the reduced number is of the form 8b + 7, it requires 4 squares; otherwise 3.
    if (temp % 8 == 7) {
        return 4;
    } else {
        return 3;
    }
}

