    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;

    // Precompute list of perfect squares up to n
    int maxRoot = (int) Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 1; i <= maxRoot; i++) {
        squares[i - 1] = i * i;
    }

    // Dynamic programming to compute minimal counts
    for (int i = 1; i <= n; i++) {
        for (int sq : squares) {
            if (sq > i) {
                break;
            }
            if (dp[i - sq] + 1 < dp[i]) {
                dp[i] = dp[i - sq] + 1;
            }
        }
    }

    return dp[n];
}

