        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
                if (min == 1) { // cannot get better than 1
                    break;
                }
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(s.length());
    int i = 0;
    while (i < s.length()) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int start = i;
            while (i < s.length() && s.charAt(i) != ' ') {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int len = s.length();
    StringBuilder result = new StringBuilder(len);
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < len; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(' ');
            word.setLength(0);
        } else {
            word.append(c);
        }
    }
    // Append the last word if there is one
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}

